mkdir -p output && cd scripts && awk -F',' '
BEGIN {
    won = 0; lost = 0; pending = 0; total_revenue = 0
}
NR > 1 {
    region = $3; amount = $5; status = $7
    gsub(/[[:space:]]/, "", status)
    deals_by_region[region]++
    if (status == "won") {
        total_revenue += amount
        revenue_by_region[region] += amount
        won++
    } else if (status == "lost") {
        lost++
    } else {
        pending++
    }
}
END {
    total = won + lost + pending
    win_rate = (total > 0) ? (won / total * 100) : 0
    sep = "============================================="
    print sep
    print "  Meridian Analytics — Q3 Sales Summary"
    print sep
    printf "  Total deals worked : %d\n", total
    printf "  Won                : %d\n", won
    printf "  Lost               : %d\n", lost
    printf "  Pending            : %d\n", pending
    printf "  Win rate           : %.1f%%\n", win_rate
    printf "  Total revenue (won): $%\047d\n", total_revenue
    print ""
    print "  Revenue by region (won deals):"
    # Sort regions by revenue descending
    n = asorti(revenue_by_region, sorted)
    # Bubble sort by revenue desc
    for (i = 1; i <= n; i++)
        for (j = i+1; j <= n; j++)
            if (revenue_by_region[sorted[i]] < revenue_by_region[sorted[j]]) {
                tmp = sorted[i]; sorted[i] = sorted[j]; sorted[j] = tmp
            }
    for (i = 1; i <= n; i++) {
        r = sorted[i]
        printf "    %-8s $%10\047d  (%d deals total)\n", r, revenue_by_region[r], deals_by_region[r]
    }
    print sep
}
' ../data/sales_q3.csv > ../output/sales_summary.txt

mkdir -p output && cd scripts && awk -F',' '
BEGIN {
    won = 0; lost = 0; pending = 0; total_revenue = 0; nregions = 0
}
NR > 1 {
    region = $3; amount = $5+0; status = $7
    gsub(/[[:space:]]/, "", status)
    if (!(region in rev_idx)) {
        rev_idx[region] = nregions
        regions[nregions] = region
        nregions++
    }
    deals_by_region[region]++
    if (status == "won") {
        total_revenue += amount
        revenue_by_region[region] += amount
        won++
    } else if (status == "lost") {
        lost++
    } else {
        pending++
    }
}
END {
    total = won + lost + pending
    win_rate = (total > 0) ? (won / total * 100) : 0
    sep = "============================================="
    print sep
    print "  Meridian Analytics — Q3 Sales Summary"
    print sep
    printf "  Total deals worked : %d\n", total
    printf "  Won                : %d\n", won
    printf "  Lost               : %d\n", lost
    printf "  Pending            : %d\n", pending
    printf "  Win rate           : %.1f%%\n", win_rate
    printf "  Total revenue (won): $%d\n", total_revenue
    print ""
    print "  Revenue by region (won deals):"
    # Bubble sort regions by revenue descending
    for (i = 0; i < nregions; i++)
        for (j = i+1; j < nregions; j++)
            if (revenue_by_region[regions[i]] < revenue_by_region[regions[j]]) {
                tmp = regions[i]; regions[i] = regions[j]; regions[j] = tmp
            }
    for (i = 0; i < nregions; i++) {
        r = regions[i]
        if (revenue_by_region[r] > 0)
            printf "    %-8s $%10d  (%d deals total)\n", r, revenue_by_region[r], deals_by_region[r]
    }
    print sep
}
' ../data/sales_q3.csv > ../output/sales_summary.txt
